 settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM9 3l-.6 2.1L6.5 6 4.4 5.5 2.5 9l1.5 1.6v2.8L2.5 15l1.9 3.5 2.1-.5 1.9.9L9 21h6l.6-2.1 1.9-.9 2.1.5 1.9-3.5-1.5-1.6v-2.8L21.5 9l-1.9-3.5-2.1.5-1.9-.9L15 3Z',
 arrow:'M5 12h14M14 7l5 5-5 5', chevron:'M9 5l7 7-7 7',down:'m6 9 6 6 6-6', plus:'M12 5v14M5 12h14',close:'M6 6l12 12M6 18 18 6',check:'m5 12 4 4L19 6',
 pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',
 area:'M3 8V3h5M16 3h5v5M21 16v5h-5M8 21H3v-5M8 8l8 8M8 8h5M8 8v5M16 16h-5M16 16v-5',
 bed:'M3 18v3M21 18v3M3 13V7a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2v6M3 13h18v5H3ZM7 9h3v4H7ZM14 9h3v4h-3Z',
 building:'M4 21V5h10v16M14 10h6v11M2 21h20M7 8h1M10 8h1M7 11h1M10 11h1M7 14h1M10 14h1M8 21v-4h3v4M17 13h1M17 16h1',
 leaf:'M20 3C8 2 2 8 5 16c7 6 16 1 15-13ZM4 21l12-12M8 17v-5M11 14h5',
 shield:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6ZM8 12l3 3 5-6',
 lock:'M6 10h12v11H6ZM8 10V6a4 4 0 1 1 8 0v4M12 14v3',
 filter:'M4 7h16M7 12h10M10 17h4M8 5v4M16 10v4M12 15v4',
 image:'M3 3h18v18H3ZM3 16l6-6 4 4 3-3 5 5M17 7h.01',
 bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',
 info:'M12 11v6M12 7h.01M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z',
 edit:'m16 3 5 5-12 12-6 1 1-6ZM13 6l5 5',
 send:'m22 2-7 20-4-9-9-4ZM22 2 11 13',
 mail:'M3 5h18v14H3ZM3 5l9 8 9-8',
 phone:'M22 16.9V20a2 2 0 0 1-2.2 2A19.8 19.8 0 0 1 3 5.2 2 2 0 0 1 5 3h3l2 5-3 2a16 16 0 0 0 7 7l2-3Z',
 menu:'M4 6h16M4 12h16M4 18h16', trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7',
 wallet:'M3 6h17v15H3ZM3 6l15-4v4M15 11h7v6h-7ZM18 14h.01',
 clock:'M12 7v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z',
 sparkle:'m12 3 2.7 6.3L21 12l-6.3 2.7L12 21l-2.7-6.3L3 12l6.3-2.7ZM20 2v4M18 4h4',
